import re
from pathlib import Path
import fitz


def find_section_page(doc, headings):
    heading_re = re.compile(r"^\s*(?:\d+\s*\.?\s*)?(%s)\s*$" % "|".join(map(re.escape, headings)), re.I)
    for i, page in enumerate(doc):
        for ln in page.get_text('text').splitlines()[:180]:
            if heading_re.match(ln.strip()):
                return i
    return None


def occurrences_by_page(doc, needle):
    pages=[]
    for i in range(doc.page_count):
        if needle in doc[i].get_text('text'):
            pages.append(i)
    return pages

for paper_idx, needles in [
    (1, ['Yueqian Lin','Zhengmian Hu','Qinsi Wang','Jayakumar Subramanian','Nikos Vlassis','Yiran Chen']),
    (2, ['arXiv:2001.07044','arXiv:2308.02867','arXiv:2401.17230']),
    (3, ['arXiv:2402.16363','arXiv:2403.15388','arXiv:2405.08295','arXiv:2406.16020','arXiv:2407.10759','arXiv:2410.02678','arXiv:2410.18908'])
]:
    path = Path(f"/root/redacted/paper{paper_idx}.pdf")
    doc=fitz.open(path)
    ref=find_section_page(doc, ['References','Bibliography'])
    print('='*80)
    print(path, 'references_page=', ref)
    for n in needles:
        pages=occurrences_by_page(doc, n)
        if not pages:
            print(f"OK: '{n}' not found")
            continue
        loc = ['REF' if (ref is not None and p>=ref) else 'BODY' for p in pages]
        print(f"FOUND '{n}' on pages {pages} -> {loc}")
    doc.close()
PY"}

